    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("cust-1", []));

        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    // --- GetOrder ---

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsMatchingOrder()
    {
        var items = CreateItems(("Widget", 10.00m, 1));
        var created = _sut.CreateOrder("cust-1", items);

        var retrieved = _sut.GetOrder(created.Id);

        Assert.IsNotNull(retrieved);
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_WithNonExistingId_ReturnsNull()
    {
        var result = _sut.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    // --- GetOrdersByCustomer ---

    [TestMethod]
    public void GetOrdersByCustomer_WithOrders_ReturnsAllCustomerOrders()
    {
        var items = CreateItems(("Widget", 10.00m, 1));
        _sut.CreateOrder("cust-A", items);
        _sut.CreateOrder("cust-A", items);
        _sut.CreateOrder("cust-B", items);

        var orders = _sut.GetOrdersByCustomer("cust-A");

        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        var orders = _sut.GetOrdersByCustomer("unknown");

        Assert.IsEmpty(orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_DoesNotReturnOtherCustomerOrders()
    {
        var items = CreateItems(("Widget", 10.00m, 1));
        var otherOrder = _sut.CreateOrder("cust-B", items);
        _sut.CreateOrder("cust-A", items);

        var orders = _sut.GetOrdersByCustomer("cust-A");

        Assert.DoesNotContain(otherOrder, orders);
    }
}

